long long sum_array(const int a[], int n) {
    long long sum = 0;
    for (int i = 0; i < n; ++i) sum += a[i];
    return sum;
}

int unique_sorted(int a[], int n) {
    if (n == 0) return 0;
    int write = 1;
    for (int read = 1; read < n; ++read) {
        if (a[read] != a[write - 1]) a[write++] = a[read];
    }
    return write;
}

typedef struct Node { int data; struct Node *next; } Node;
int list_length(const Node *head) {
    int length = 0;
    for (const Node *p = head; p != 0; p = p->next) ++length;
    return length;
}

void reverse_array(int a[], int n) {
    int left = 0, right = n - 1;
    while (left < right) {
        int temp = a[left];
        a[left++] = a[right];
        a[right--] = temp;
    }
}

int valid_parens(const char *s) {
    int balance = 0;
    for (; *s; ++s) {
        if (*s == '(') ++balance;
        else if (--balance < 0) return 0;
    }
    return balance == 0;
}

typedef struct TreeNode {
    int data; struct TreeNode *left, *right;
} TreeNode;
int tree_height(const TreeNode *root) {
    if (root == 0) return 0;
    int left = tree_height(root->left);
    int right = tree_height(root->right);
    return 1 + (left > right ? left : right);
}

int vertex_degree(int n, const int a[][100], int v) {
    int degree = 0;
    for (int j = 0; j < n; ++j) degree += a[v][j];
    return degree;
}

int binary_search(const int a[], int n, int target) {
    int left = 0, right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int is_min_heap(const int a[], int n) {
    for (int i = 1; i < n; ++i) {
        if (a[(i - 1) / 2] > a[i]) return 0;
    }
    return 1;
}

void insertion_sort(int a[], int n) {
    for (int i = 1; i < n; ++i) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) {
            a[j + 1] = a[j];
            --j;
        }
        a[j + 1] = key;
    }
}
